import { LogoCloud } from "march/landing"
import { Button } from "march/ui"

// emoji geçit töreni: kayan şeritte meyveler; düğmeler hızı değiştirir
const FRUITS = ["🍎", "🍌", "🍇", "🍉", "🍓", "🥝", "🍍", "🥥"]
const NAMES = ["Elma", "Muz", "Üzüm", "Karpuz", "Çilek", "Kivi", "Ananas", "Hindistan cevizi"]

export function EmojiParade() {
  let $speed = 40
  return <div sx={{ flex: "col", gap: 3 }}>
    <div sx={{ flex: ["row", "center"], gap: 2 }}>
      <Button variant="secondary" on:click={() => $speed = Math.max(10, $speed - 20)}>Yavaşla</Button>
      <strong>{`${$speed} px/sn`}</strong>
      <Button variant="secondary" on:click={() => $speed = Math.min(160, $speed + 20)}>Hızlan</Button>
    </div>
    {() => {
      const speed = $speed
      return <LogoCloud variant="marquee" mono={false} speed={speed} title="Meyve geçidi"
      logos={FRUITS.map((f, i) => ({ name: NAMES[i]!, node: <span sx={{ text: "2xl" }}>{f}</span> }))} />
    }}
  </div>
}

import { LogoCloud } from "march/landing"
import { Card, Segmented, Toggle } from "march/ui"

// LogoCloud'un bütün özellikleri bir arada: logolar (name, src, width, height, node, href), görünüm (variant),
// başlık (title), tek ton (mono), hız (speed), giriş hareketi (reveal) ve sınıf (class)
const Dot = (p: { fill: string; label: string }) => <svg width="96" height="28" viewBox="0 0 96 28" aria-hidden="true">
  <circle cx="14" cy="14" r="10" fill={p.fill} /><text x="30" y="19" font-size="13" fill="currentColor">{p.label}</text>
</svg>

export function LogoCloudLab() {
  let $variant: "grid" | "marquee" = "grid"
  let $mono = true
  let $count = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <Card>
      <div sx={{ flex: ["row", "wrap"], gap: 3 }}>
        <Segmented aria-label="Görünüm" options={[{ value: "grid", label: "grid" }, { value: "marquee", label: "marquee" }]} bind:value={$variant} />
        <Toggle label="Tek ton" bind:value={$mono} />
      </div>
    </Card>
    {() => {
      // bu satırda okunan durumlar değişince bulut yeniden çizilir; başlık bir işlev, kendisi güncellenir
      const variant = $variant, mono = $mono
      return <LogoCloud variant={variant} mono={mono} speed={30} reveal="none" class="lab-logos"
      title={() => `Bize güvenen ${4 + $count} ekip`}
      logos={[
        { name: "Dalga", src: "/media/hadi-waves.jpg", width: 96, height: 28 },
        { name: "Turuncu", node: <Dot fill="#ff7a59" label="Turuncu" />, href: "#turuncu" },
        { name: "Mor", node: <Dot fill="#7c5cff" label="Mor" /> },
        { name: "Mavi", node: <Dot fill="#2bb8ff" label="Mavi" /> },
      ]} />
    }}
    <button type="button" on:click={() => $count++}>Ekip ekle</button>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { LogoCloudLab } from "./LogoCloudLab.tsx"

// LogoCloudLab'in testleri: kaydedince Testler sekmesinde çalışır
test("ızgarada dört hücre, başlık ve tek ton", () => {
  const s = renderTest(() => <LogoCloudLab />)
  expect(s.all(".lab-logos .m-logos-cell").length).toBe(4)
  expect(s.get(".m-logos-title")?.textContent).toBe("Bize güvenen 4 ekip")
  expect(s.get(".lab-logos")?.classList.contains("is-mono")).toBe(true)
})

test("resimli logonun alt metni, bağlantılı logonun adı var", () => {
  const s = renderTest(() => <LogoCloudLab />)
  expect(s.get('.lab-logos img[alt="Dalga"]')).not.toBe(null)
  expect(s.get('.lab-logos a[href="#turuncu"]')?.getAttribute("aria-label")).toBe("Turuncu")
})

test("başlık bir işlev: düğmeyle değişir", async () => {
  const s = renderTest(() => <LogoCloudLab />)
  await s.click("Ekip ekle")
  expect(s.get(".m-logos-title")?.textContent).toBe("Bize güvenen 5 ekip")
})

test("marquee'ye geçince şerit gelir; tek ton kapanır", async () => {
  const s = renderTest(() => <LogoCloudLab />)
  await s.click("marquee")
  await s.click("Tek ton")
  expect(s.get(".lab-logos .m-logos-marquee")).not.toBe(null)
  expect(s.get(".lab-logos")?.classList.contains("is-mono")).toBe(false)
})
